CREATE OR REPLACE FUNCTION public.company_sales_orders() RETURNS TABLE(id uuid,listing_id uuid,title text,amount numeric,fee numeric,quantity integer,status text,created_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.community_account_active() OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.is_company) THEN RAISE EXCEPTION 'COMPANY_ACCOUNT_REQUIRED'; END IF; RETURN QUERY SELECT o.id,o.listing_id,coalesce(l.title,'—'),o.amount,o.fee,o.quantity,o.status::text,o.created_at FROM public.orders o LEFT JOIN public.listings l ON l.id=o.listing_id WHERE o.seller_id=auth.uid() ORDER BY o.created_at DESC; END $$;
ALTER POLICY conv_country_boundary ON public.conversations USING(public.can_access_conversation(id) OR ((buyer_id=auth.uid() OR seller_id=auth.uid()) AND (company_trade OR public.same_community(buyer_id,seller_id))));